import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.Scanner;

public class SecurePathTraversal {

    private static final String BASE_DIRECTORY = "path/to/secure/directory/";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter file name: ");
        String fileName = scanner.nextLine();

        try {
            File requestedFile = new File(BASE_DIRECTORY + fileName);
            if (requestedFile.getCanonicalPath().startsWith(BASE_DIRECTORY)) {
                FileReader fileReader = new FileReader(requestedFile);
                int data;
                while ((data = fileReader.read()) != -1) {
                    System.out.print((char) data);
                }
                fileReader.close();
            } else {
                System.out.println("Access to this file is not allowed.");
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
    }
}

