    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");

        // Sanitize user input to prevent XSS attacks
        String safeUserInput = sanitizeInput(userInput);

        String htmlResponse = "<html><body><h1>Welcome " + safeUserInput + "</h1></body></html>";

        response.setContentType("text/html");
        response.getWriter().write(htmlResponse);
    }

    private String sanitizeInput(String input) {
        // Replace special characters that can be used in XSS attacks with their HTML entity equivalents
        return input.replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("&", "&amp;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#39;");
    }
}

