import java.io.IOException;
import javax.servlet.http.*;

public class XSSSecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");

        // Sanitize and escape user input to prevent XSS
        userInput = sanitizeInput(userInput);

        String htmlResponse = "<html><body><h1>User Input:</h1>" + userInput + "</body></html>";

        response.getWriter().write(htmlResponse);
    }

    private String sanitizeInput(String input) {
        if (input == null) {
            return "";
        }

        // Replace special characters with HTML entities to prevent XSS
        input = input.replaceAll("&", "&amp;")
                     .replaceAll("<", "&lt;")
                     .replaceAll(">", "&gt;")
                     .replaceAll("\"", "&quot;")
                     .replaceAll("'", "&#39;");

        return input;
    }
}

