    private String sanitizeInput(String input) {
        // Encode HTML special characters to prevent XSS
        return input != null ? input.replace("&", "&amp;")
                                    .replace("<", "&lt;")
                                    .replace(">", "&gt;")
                                    .replace("\"", "&quot;")
                                    .replace("'", "&#39;") : "";
    }
}

