public class SecureBufferExample {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter a string:");
        String userInput = scanner.nextLine();

        char[] buffer = new char[10]; // Buffer size is fixed at 10

        // Copy user input into the buffer (secure copy)
        int length = Math.min(userInput.length(), buffer.length);
        userInput.getChars(0, length, buffer, 0);

        // Fill remaining space with null characters
        Arrays.fill(buffer, length, buffer.length, '\0');

        System.out.println("Buffer contents: " + new String(buffer));
