import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class XSSFixedServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Sanitize user input to prevent XSS
        String sanitizedInput = sanitizeInput(userInput);

        // Construct HTML response with sanitized input
        String output = "<html><body><h1>User Input: " + sanitizedInput + "</h1></body></html>";

        PrintWriter out = response.getWriter();
        out.println(output);
    }

    // Method to sanitize user input to prevent XSS
    private String sanitizeInput(String input) {
        return input != null ? input.replace("<", "&lt;").replace(">", "&gt;") : "";
    }
}

