import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.owasp.esapi.ESAPI;
import org.owasp.esapi.Encoder;

public class SecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Encode user input to prevent XSS
        Encoder encoder = ESAPI.encoder();
        String encodedInput = encoder.encodeForHTML(userInput);

        // Properly handling user input by encoding it before outputting it to the response
        PrintWriter out = response.getWriter();
        out.println("<html><body>");
        out.println("<h1>User Input: " + encodedInput + "</h1>");
        out.println("</body></html>");
    }
}

