    private String escapeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replaceAll("<", "&lt;")
                     .replaceAll(">", "&gt;")
                     .replaceAll("\"", "&quot;")
                     .replaceAll("'", "&#39;")
                     .replaceAll("&", "&amp;");
    }
}

