import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String input = scanner.nextLine();

        // Define a maximum buffer size to prevent buffer overflow
        int maxSize = 10;

        // Truncate the input if it exceeds the maximum buffer size
        if (input.length() > maxSize) {
            input = input.substring(0, maxSize);
            System.out.println("Input exceeded maximum length. Truncated to: " + input);
        }

        char[] buffer = new char[maxSize];

        // Copy the characters from input to buffer
        input.getChars(0, Math.min(input.length(), maxSize), buffer, 0);

        System.out.println("Hello, " + new String(buffer));
    }
}

