        out.println("<html><body>");
        out.println("<h1>User Input: " + encodeHtml(userInput) + "</h1>");
        out.println("</body></html>");
    }

    private String encodeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;")
                    .replace("/", "&#x2F;");
    }
}

