public class SecureBuffer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        // Creating a fixed-size char array with size 10
        char[] buffer = new char[10];

        // Ensuring user input does not exceed buffer size
        int copyLength = Math.min(userInput.length(), buffer.length);

        // Copying user input into the buffer array safely
        userInput.getChars(0, copyLength, buffer, 0);

        System.out.println("Buffer content: " + new String(buffer));
    }
