        // Update the 'promise' hierarchy with the concrete implementation.
        final CliCommandHierarchyImpl cliHierarchy = new CliCommandHierarchyImpl(root, systemCommands);
        hierarchyPromise.setDelegate(cliHierarchy);
        return cliHierarchy;
