        String userInput = request.getParameter("input");
        String sanitizedUserInput = escapeHtml(userInput);
        String output = "<h1>Welcome " + sanitizedUserInput + "</h1>";

        PrintWriter out = response.getWriter();
        out.println(output);
    }

    private String escapeHtml(String input) {
        return input != null ? input
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;") : "";
    }
}

