                // The run() method will report this as an error later
                if (isTraceOn && tc.isDebugEnabled())
                    Tr.debug(tc, "Timer method no longer present on bean??");
            }
        } else {
            if (isTraceOn && tc.isDebugEnabled())
                Tr.debug(tc, "not a container managed concurrency singleton bean");
        }

